import { seededNoise } from '../../../core/uvvis/synthetic';
import type { Spectrum } from '../../../core/uvvis/types';
import type { ConcentrationSample } from './data';

/** The made-up dye of the example: one Gaussian band. Not a real compound. */
export const EXAMPLE_DYE = {
  peakNm: 660,
  widthNm: 35,
  /** Absorbance per mg/L in a 1 cm cell at the peak. */
  absorptivity: 0.18,
  /** Pseudo-first-order rate constant of the made-up degradation, 1/min. */
  kPerMin: 0.02,
  startMgL: 5,
};

const NOTE =
  'Synthetic example generated by this site: a made-up dye band. It is not a measurement of any real compound.';

function spectrum(name: string, concentration: number, seed: number): Spectrum {
  const noise = seededNoise(seed, 0.002);
  const wavelengthNm = Float64Array.from({ length: 401 }, (_, i) => 400 + i);
  const { peakNm, widthNm, absorptivity } = EXAMPLE_DYE;
  return {
    id: crypto.randomUUID(),
    name,
    source: 'synthetic',
    wavelengthNm,
    values: wavelengthNm.map(
      (w) =>
        absorptivity * concentration * Math.exp(-0.5 * ((w - peakNm) / widthNm) ** 2) + noise(),
    ),
    kind: 'absorbance',
    scale: 'fraction',
    kindOrigin: 'generated',
    synthetic: true,
    notes: [{ level: 'info', text: NOTE }],
  };
}

/** Five standards (1 to 8 mg/L) and a degradation series with a 30 min dark period. */
export function exampleSamples(): ConcentrationSample[] {
  const standards = [1, 2, 4, 6, 8].map((c, i): ConcentrationSample => ({
    id: crypto.randomUUID(),
    role: 'standard',
    name: `Standard ${c} mg/L (synthetic)`,
    spectrum: spectrum(`Standard ${c} mg/L (synthetic)`, c, 100 + i),
    typedAbsorbance: null,
    value: c,
  }));
  const { kPerMin, startMgL } = EXAMPLE_DYE;
  // Before the light is switched on (t < 0) the dye only adsorbs: the concentration drops to 90 %.
  const timed = [-30, 0, 15, 30, 45, 60, 90, 120].map((t, i): ConcentrationSample => {
    const c = t < 0 ? startMgL : 0.9 * startMgL * Math.exp(-kPerMin * t);
    return {
      id: crypto.randomUUID(),
      role: 'timed',
      name: `${t} min (synthetic)`,
      spectrum: spectrum(`${t} min (synthetic)`, c, 200 + i),
      typedAbsorbance: null,
      value: t,
    };
  });
  return [...standards, ...timed];
}
